--
-- Table structure for table `booking_qr_codes`
--

DROP TABLE IF EXISTS `booking_qr_codes`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `booking_qr_codes` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` int unsigned NOT NULL,
  `booking_id` int unsigned NOT NULL,
  `qr_token` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `qr_path` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `expired_at` datetime DEFAULT NULL,
  `used_at` datetime DEFAULT NULL,
  `status` enum('active','used','expired','revoked') COLLATE utf8mb4_general_ci DEFAULT 'active',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_qr_token` (`qr_token`),
  KEY `idx_qr_booking_status` (`booking_id`,`status`),
  KEY `fk_qr_tenant` (`tenant_id`),
  CONSTRAINT `fk_qr_booking` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_qr_tenant` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=196 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

