--
-- Table structure for table `booking_recurring_templates`
--

DROP TABLE IF EXISTS `booking_recurring_templates`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `booking_recurring_templates` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` int unsigned NOT NULL,
  `branch_id` int unsigned NOT NULL,
  `court_id` int unsigned NOT NULL,
  `player_id` int unsigned DEFAULT NULL,
  `name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `start_date` date NOT NULL,
  `end_date` date DEFAULT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `duration_minutes` int NOT NULL,
  `repeat_type` enum('daily','weekly','biweekly','monthly','custom') COLLATE utf8mb4_general_ci NOT NULL,
  `repeat_interval` int NOT NULL DEFAULT '1',
  `repeat_days` json DEFAULT NULL,
  `exclude_dates` json DEFAULT NULL,
  `status` enum('active','paused','completed','cancelled') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active',
  `total_occurrences` int NOT NULL DEFAULT '0',
  `completed_occurrences` int NOT NULL DEFAULT '0',
  `next_occurrence` date DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `booking_recurring_templates_branch_id_foreign` (`branch_id`),
  KEY `booking_recurring_templates_court_id_foreign` (`court_id`),
  KEY `tenant_id_status_next_occurrence` (`tenant_id`,`status`,`next_occurrence`),
  CONSTRAINT `booking_recurring_templates_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `booking_recurring_templates_court_id_foreign` FOREIGN KEY (`court_id`) REFERENCES `courts` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `booking_recurring_templates_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

