DROP TABLE IF EXISTS `coaching_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `coaching_sessions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` int unsigned NOT NULL,
  `branch_id` int unsigned NOT NULL,
  `coach_id` int unsigned NOT NULL,
  `court_id` int unsigned DEFAULT NULL,
  `booking_id` int unsigned DEFAULT NULL,
  `title` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `session_type` enum('private','semi_private','group','clinic') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'private',
  `session_date` date NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `capacity` smallint unsigned NOT NULL DEFAULT '1',
  `price_per_player` decimal(12,2) NOT NULL DEFAULT '0.00',
  `status` enum('draft','open','full','started','completed','cancelled') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'draft',
  `notes` text COLLATE utf8mb4_general_ci,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `coaching_sessions_branch_id_foreign` (`branch_id`),
  KEY `coaching_sessions_coach_id_foreign` (`coach_id`),
  KEY `coaching_sessions_court_id_foreign` (`court_id`),
  KEY `coaching_sessions_booking_id_foreign` (`booking_id`),
  KEY `tenant_id_session_date_status` (`tenant_id`,`session_date`,`status`),
  CONSTRAINT `coaching_sessions_booking_id_foreign` FOREIGN KEY (`booking_id`) REFERENCES `bookings` (`id`) ON DELETE CASCADE ON UPDATE SET NULL,
  CONSTRAINT `coaching_sessions_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `coaching_sessions_coach_id_foreign` FOREIGN KEY (`coach_id`) REFERENCES `coaches` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `coaching_sessions_court_id_foreign` FOREIGN KEY (`court_id`) REFERENCES `courts` (`id`) ON DELETE CASCADE ON UPDATE SET NULL,
  CONSTRAINT `coaching_sessions_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=24 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
