DROP TABLE IF EXISTS `customers`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `customers` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` int unsigned NOT NULL,
  `player_id` int unsigned DEFAULT NULL,
  `full_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `phone` varchar(30) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `email` varchar(255) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `status` enum('active','inactive','merged') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'active',
  `source` enum('booking','player','admin','import','api','other') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'booking',
  `first_seen_at` datetime DEFAULT NULL,
  `last_seen_at` datetime DEFAULT NULL,
  `last_booking_at` datetime DEFAULT NULL,
  `last_visit_at` datetime DEFAULT NULL,
  `total_bookings` int unsigned NOT NULL DEFAULT '0',
  `completed_bookings` int unsigned NOT NULL DEFAULT '0',
  `no_show_count` int unsigned NOT NULL DEFAULT '0',
  `total_spend` decimal(14,2) NOT NULL DEFAULT '0.00',
  `favorite_court_id` int unsigned DEFAULT NULL,
  `metadata` json DEFAULT NULL,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tenant_id_status` (`tenant_id`,`status`),
  KEY `tenant_id_phone` (`tenant_id`,`phone`),
  KEY `tenant_id_email` (`tenant_id`,`email`),
  KEY `tenant_id_player_id` (`tenant_id`,`player_id`)
) ENGINE=InnoDB AUTO_INCREMENT=157 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

