--
-- Table structure for table `daily_closings`
--

DROP TABLE IF EXISTS `daily_closings`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `daily_closings` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` int unsigned NOT NULL,
  `branch_id` int unsigned DEFAULT NULL,
  `closing_date` date NOT NULL,
  `status` enum('open','closed','reopened') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'open',
  `cash_total` decimal(14,2) NOT NULL DEFAULT '0.00',
  `qr_total` decimal(14,2) NOT NULL DEFAULT '0.00',
  `wallet_total` decimal(14,2) NOT NULL DEFAULT '0.00',
  `other_total` decimal(14,2) NOT NULL DEFAULT '0.00',
  `billed_total` decimal(14,2) NOT NULL DEFAULT '0.00',
  `collected_total` decimal(14,2) NOT NULL DEFAULT '0.00',
  `refund_total` decimal(14,2) NOT NULL DEFAULT '0.00',
  `discrepancy_amount` decimal(14,2) NOT NULL DEFAULT '0.00',
  `notes` text COLLATE utf8mb4_general_ci,
  `closed_by` int unsigned DEFAULT NULL,
  `closed_at` datetime DEFAULT NULL,
  `reopened_by` int unsigned DEFAULT NULL,
  `reopened_at` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `tenant_id_branch_id_closing_date` (`tenant_id`,`branch_id`,`closing_date`),
  KEY `tenant_id_closing_date` (`tenant_id`,`closing_date`)
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

