INSERT INTO `notification_templates` VALUES (1,'password_reset','email','vi','Đặt lại mật khẩu - {{site_name}}','<p>Chào {{full_name}},</p><p>Bạn vừa yêu cầu đặt lại mật khẩu. Nhấn vào liên kết bên dưới:</p><p><a href=\'{{reset_url}}\'>Đặt lại mật khẩu</a></p><p>Liên kết hết hạn sau {{expires}} phút.</p>','[\"site_name\", \"full_name\", \"reset_url\", \"expires\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(2,'password_reset','email','en','Reset your password - {{site_name}}','<p>Hi {{full_name}},</p><p>You requested a password reset. Click the link below:</p><p><a href=\'{{reset_url}}\'>Reset password</a></p><p>The link expires in {{expires}} minutes.</p>','[\"site_name\", \"full_name\", \"reset_url\", \"expires\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(3,'booking_confirmation','email','vi','Xác nhận đặt sân {{booking_code}}','<p>Chào {{customer_name}},</p><p>Đặt sân của bạn đã được xác nhận:</p><ul><li>Mã đặt: {{booking_code}}</li><li>Sân: {{court_name}}</li><li>Thờị gian: {{start_time}} - {{end_time}}</li><li>Tổng tiền: {{total_amount}}</li></ul>','[\"customer_name\", \"booking_code\", \"court_name\", \"start_time\", \"end_time\", \"total_amount\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(4,'booking_confirmation','email','en','Booking confirmation {{booking_code}}','<p>Hi {{customer_name}},</p><p>Your booking is confirmed:</p><ul><li>Code: {{booking_code}}</li><li>Court: {{court_name}}</li><li>Time: {{start_time}} - {{end_time}}</li><li>Total: {{total_amount}}</li></ul>','[\"customer_name\", \"booking_code\", \"court_name\", \"start_time\", \"end_time\", \"total_amount\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(5,'welcome_user','in_app','vi','Chào mừng {{full_name}}','Tài khoản của bạn đã được tạo trên {{site_name}}.','[\"full_name\", \"site_name\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(6,'welcome_user','in_app','en','Welcome {{full_name}}','Your account has been created on {{site_name}}.','[\"full_name\", \"site_name\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(7,'booking_reminder','in_app','vi','Nhắc nhở đặt sân {{booking_code}}','Bạn có lịch đặt sân {{court_name}} vào {{start_time}}.','[\"booking_code\", \"court_name\", \"start_time\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(8,'booking_reminder','in_app','en','Booking reminder {{booking_code}}','You have a court booking at {{court_name}} on {{start_time}}.','[\"booking_code\", \"court_name\", \"start_time\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(9,'coaching_player_approved','in_app','vi','Coaching đã được duyệt','Bạn đã được duyệt vào session {{session_title}}.','[\"full_name\", \"session_title\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(10,'coaching_player_approved','in_app','en','Coaching approved','You were approved for {{session_title}}.','[\"full_name\", \"session_title\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(11,'ladder_challenge_received','in_app','vi','Bạn nhận được ladder challenge','{{challenger_name}} đã thách đấu bạn trong {{event_name}}.','[\"challenger_name\", \"event_name\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(12,'ladder_challenge_received','in_app','en','New ladder challenge','{{challenger_name}} challenged you in {{event_name}}.','[\"challenger_name\", \"event_name\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(13,'ladder_challenge_accepted','in_app','vi','Ladder challenge được chấp nhận','{{opponent_name}} đã chấp nhận challenge của bạn.','[\"opponent_name\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(14,'ladder_challenge_accepted','in_app','en','Ladder challenge accepted','{{opponent_name}} accepted your challenge.','[\"opponent_name\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(15,'ladder_challenge_rejected','in_app','vi','Ladder challenge bị từ chối','{{opponent_name}} đã từ chối challenge của bạn.','[\"opponent_name\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL),(16,'ladder_challenge_rejected','in_app','en','Ladder challenge rejected','{{opponent_name}} rejected your challenge.','[\"opponent_name\"]',1,1,1,'2026-08-09 17:28:23','2026-08-11 12:00:29',NULL);
