--
-- Table structure for table `open_play_sessions`
--

DROP TABLE IF EXISTS `open_play_sessions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `open_play_sessions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` int unsigned NOT NULL,
  `branch_id` int unsigned NOT NULL,
  `host_player_id` int unsigned NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `session_date` date NOT NULL,
  `start_time` time NOT NULL,
  `end_time` time NOT NULL,
  `capacity` smallint unsigned NOT NULL DEFAULT '4',
  `min_level` varchar(30) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `max_level` varchar(30) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `price_per_player` decimal(12,2) NOT NULL DEFAULT '0.00',
  `visibility` enum('public','private','club_only') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'public',
  `status` enum('draft','open','full','started','completed','cancelled') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'draft',
  `notes` text COLLATE utf8mb4_general_ci,
  `created_by` int unsigned DEFAULT NULL,
  `updated_by` int unsigned DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `open_play_sessions_branch_id_foreign` (`branch_id`),
  KEY `open_play_sessions_host_player_id_foreign` (`host_player_id`),
  KEY `tenant_id_session_date_status` (`tenant_id`,`session_date`,`status`),
  KEY `tenant_id_branch_id_session_date` (`tenant_id`,`branch_id`,`session_date`),
  CONSTRAINT `open_play_sessions_branch_id_foreign` FOREIGN KEY (`branch_id`) REFERENCES `branches` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `open_play_sessions_host_player_id_foreign` FOREIGN KEY (`host_player_id`) REFERENCES `players` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `open_play_sessions_tenant_id_foreign` FOREIGN KEY (`tenant_id`) REFERENCES `tenants` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=30 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `open_play_sessions`
--

LOCK TABLES `open_play_sessions` WRITE;
