--
-- Table structure for table `rating_transactions`
--

DROP TABLE IF EXISTS `rating_transactions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `rating_transactions` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` int unsigned NOT NULL,
  `player_id` int unsigned NOT NULL,
  `provider_id` int unsigned NOT NULL,
  `discipline_id` int unsigned NOT NULL,
  `match_id` int unsigned DEFAULT NULL,
  `match_result_version_id` int unsigned DEFAULT NULL,
  `rating_policy_version_id` int unsigned NOT NULL,
  `transaction_type` enum('impact','reversal','replacement','adjustment','seed') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'impact',
  `before_rating` decimal(6,3) DEFAULT NULL,
  `after_rating` decimal(6,3) DEFAULT NULL,
  `rating_delta` decimal(6,3) NOT NULL,
  `expected_performance` decimal(6,4) DEFAULT NULL,
  `actual_performance` decimal(6,4) DEFAULT NULL,
  `reliability_before` decimal(5,2) NOT NULL DEFAULT '0.00',
  `reliability_after` decimal(5,2) NOT NULL DEFAULT '0.00',
  `match_weight` decimal(5,3) NOT NULL DEFAULT '1.000',
  `reason` varchar(120) COLLATE utf8mb4_general_ci NOT NULL,
  `status` enum('applied','reversed','voided') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'applied',
  `idempotency_key` varchar(220) COLLATE utf8mb4_general_ci NOT NULL,
  `processed_at` datetime DEFAULT NULL,
  `metadata` json DEFAULT NULL,
  `created_at` datetime DEFAULT NULL,
  `provenance_id` bigint unsigned DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `idempotency_key` (`idempotency_key`),
  KEY `tenant_id_player_id_discipline_id_created_at` (`tenant_id`,`player_id`,`discipline_id`,`created_at`),
  KEY `match_id_match_result_version_id_status` (`match_id`,`match_result_version_id`,`status`)
) ENGINE=InnoDB AUTO_INCREMENT=1543 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

