--
-- Table structure for table `tournament_matches`
--

DROP TABLE IF EXISTS `tournament_matches`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tournament_matches` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` int unsigned NOT NULL,
  `tournament_id` int unsigned NOT NULL,
  `category_id` int unsigned NOT NULL,
  `group_id` int unsigned DEFAULT NULL,
  `round_name` varchar(100) COLLATE utf8mb4_general_ci NOT NULL,
  `match_no` int NOT NULL,
  `court_id` int unsigned DEFAULT NULL,
  `scheduled_date` date DEFAULT NULL,
  `start_time` time DEFAULT NULL,
  `end_time` time DEFAULT NULL,
  `team_a_id` int unsigned DEFAULT NULL,
  `team_b_id` int unsigned DEFAULT NULL,
  `winner_team_id` int unsigned DEFAULT NULL,
  `unified_match_id` int unsigned DEFAULT NULL,
  `status` enum('scheduled','called','on_court','running','in_progress','delayed','completed','no_show','walkover','cancelled') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'scheduled',
  `called_at` datetime DEFAULT NULL,
  `actual_start_time` datetime DEFAULT NULL,
  `completed_at` datetime DEFAULT NULL,
  `operations_note` varchar(500) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `is_locked` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tenant_id_tournament_id_category_id` (`tenant_id`,`tournament_id`,`category_id`),
  KEY `court_id_scheduled_date_start_time` (`court_id`,`scheduled_date`,`start_time`)
) ENGINE=InnoDB AUTO_INCREMENT=129 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

