--
-- Table structure for table `tournament_registrations`
--

DROP TABLE IF EXISTS `tournament_registrations`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `tournament_registrations` (
  `id` int unsigned NOT NULL AUTO_INCREMENT,
  `tenant_id` int unsigned NOT NULL,
  `tournament_id` int unsigned NOT NULL,
  `category_id` int unsigned NOT NULL,
  `player_id` int unsigned DEFAULT NULL,
  `team_id` int unsigned DEFAULT NULL,
  `partner_player_id` int unsigned DEFAULT NULL,
  `contact_name` varchar(255) COLLATE utf8mb4_general_ci NOT NULL,
  `contact_phone` varchar(30) COLLATE utf8mb4_general_ci NOT NULL,
  `payment_status` varchar(30) COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'unpaid',
  `approval_status` enum('pending','approved','rejected') COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'pending',
  `registration_status` enum('draft','pending','confirmed','waitlisted','cancelled') COLLATE utf8mb4_general_ci DEFAULT 'draft',
  `eligibility_status` enum('pending','passed','flagged') COLLATE utf8mb4_general_ci DEFAULT 'pending',
  `checked_in_at` datetime DEFAULT NULL,
  `checkin_status` enum('pending','checked_in','no_show') COLLATE utf8mb4_general_ci DEFAULT 'pending',
  `no_show` tinyint(1) DEFAULT '0',
  `waitlist_position` int unsigned DEFAULT NULL,
  `note` text COLLATE utf8mb4_general_ci,
  `invoice_code` varchar(80) COLLATE utf8mb4_general_ci DEFAULT NULL,
  `invoice_amount` decimal(12,2) NOT NULL DEFAULT '0.00',
  `created_at` datetime DEFAULT NULL,
  `updated_at` datetime DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `tenant_id_tournament_id_category_id` (`tenant_id`,`tournament_id`,`category_id`)
) ENGINE=InnoDB AUTO_INCREMENT=159 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

