INSERT INTO `tournament_templates` VALUES (1,2,15,'Demo Summer Cup · Mẫu hàng tháng','Mẫu giải hàng tháng: đổi ngày, mở đăng ký và dùng lại cấu hình.','{\"name_en\": \"Demo Summer Cup 2026\", \"name_vi\": \"Demo Summer Cup 2026\", \"sponsors\": [{\"status\": \"active\", \"website\": \"https://example.com\", \"sort_order\": 1, \"sponsor_name\": \"Demo Sports\"}], \"branch_id\": 3, \"max_teams\": 16, \"categories\": [{\"status\": \"active\", \"name_en\": \"Mixed Doubles Open\", \"name_vi\": \"Đôi nam nữ phong trào\", \"max_teams\": \"4\", \"max_rating\": \"1800\", \"min_rating\": \"800\", \"category_type\": \"mixed_double\", \"registration_fee\": \"250000.00\"}], \"description_en\": \"Four-team demo tournament with registration, schedule, knockout bracket and public results.\", \"description_vi\": \"Giải đấu mẫu 4 đội với đăng ký, lịch thi đấu, cây knockout và kết quả công khai.\", \"rule_content_en\": \"Games to 11, win by 2, cap at 15.\", \"rule_content_vi\": \"Thi đấu chạm 11, cách 2, tối đa 15.\", \"registration_fee\": 250000}',1,NULL,'2026-08-11 09:31:23','2026-08-11 12:00:30'),(2,3,1,'Demo Summer Cup · Mẫu hàng tháng','Mẫu giải hàng tháng: đổi ngày, mở đăng ký và dùng lại cấu hình.','{\"name_en\": \"Demo Summer Cup 2026\", \"name_vi\": \"Demo Summer Cup 2026\", \"sponsors\": [{\"status\": \"active\", \"website\": \"https://example.com\", \"sort_order\": 1, \"sponsor_name\": \"Demo Sports\"}], \"branch_id\": 9, \"max_teams\": 16, \"categories\": [{\"status\": \"active\", \"name_en\": \"Mixed Doubles Open\", \"name_vi\": \"Đôi nam nữ phong trào\", \"max_teams\": \"4\", \"max_rating\": \"1800\", \"min_rating\": \"800\", \"category_type\": \"mixed_double\", \"registration_fee\": \"250000.00\"}], \"description_en\": \"Four-team demo tournament with registration, schedule, knockout bracket and public results.\", \"description_vi\": \"Giải đấu mẫu 4 đội với đăng ký, lịch thi đấu, cây knockout và kết quả công khai.\", \"rule_content_en\": \"Games to 11, win by 2, cap at